def chain_follow(WELL_FORMED):
    chain = []
    current_char = WELL_FORMED[0][0]
    for char in WELL_FORMED:
        if char == current_char:
            chain.append(char)
        else:
            if chain:
                chain.append(chain.pop())
            current_char = char
    return chain

WELL_FORMED = [
    ("bbb", "ccc"),
    ("aaa", "bbb"),
    ("ddd", "ccc")
]

chain = chain_follow(WELL_FORMED)
print(','.join(chain))
